mapper.select:
		SELECT s.SUBMISSION_ID, s.ASSIGNMENT_ID, s.STUDENT_ID, s.CONTENT, s.FILE_NAME,
       		s.SUBMITTED_AT, s.SCORE, s.FEEDBACK, s.STATUS_CD
		FROM TB_SUBMISSION s


			s.ASSIGNMENT_ID = #{assignmentId}


			AND s.STUDENT_ID = #{studentId}


		ORDER BY s.SUBMITTED_AT

mapper.update:
UPDATE TB_SUBMISSION s
SET s.CONTENT = #{content},
	s.FILE_NAME = #{fileName},
	s.SUBMITTED_AT = #{submittedAt}
WHERE s.SUBMISSION_ID = #{submissionId}

UPDATE TB_SUBMISSION s
SET s.SCORE = #{score},
	s.FEEDBACK = #{feedback},
	s.STATUS_CD = #{statusCd}
WHERE s.SUBMISSION_ID = #{submissionId}
